/*
 * tm2.js - Parser and generator for the Waves System "Scheduler V2" (.tm2) file.
 *
 * Format reverse-engineered from the official Scheduler 2.3.3.0 software
 * (app/Devices/01 (E)VP3x0 Video Player.xml and MainForm.SaveTM2SchedulerFile).
 * Validated byte-for-byte against reference .tm2 files generated by the tool.
 *
 * File layout (buffer pre-filled with 0xFF):
 *   header                    (0x644 bytes)
 *   calendar                  (u16 LE per date at 2048 + 2*(dayOfYear + 366*(year-2000)))
 *   minute blocks             (2880 bytes per typical day at 0x12600, u16 LE = code<<12 | value)
 *   typical day titles        (192 bytes each: 128 name + R G B)
 *   sequential event list     (130 bytes each: u16 LE + 128-byte comment)
 * total = 75264 + numDays*3072 + numEvents*130
 *
 * Command codes (high nibble of the event word):
 *   0x00 PLAY FOLDER   value = folder 0..999
 *   0x01 PLAYBACK      value = 1 (PLAY) | 2 (STOP)
 *   0x02 STANDBY/WAKEUP value = 1 (STANDBY) | 2 (WAKEUP)
 *   0x03 HDMI-CEC      value = 1 (STANDBY) | 2 (WAKEUP)
 *   0x05 PJLINK        value = 1 (POWER ON) | 2 (POWER OFF)
 */

(function (root, factory) {
  if (typeof module === 'object' && module.exports) module.exports = factory();
  else root.TM2 = factory();
})(typeof self !== 'undefined' ? self : this, function () {
  'use strict';

  const BASE = 75264; // 0x12600
  const MINUTE_BLOCK = 2880; // 1440 minutes * 2 bytes
  const DAY_TITLE = 192;
  const EVENT_SLOT = 130;
  const CAL_BASE = 2048;

  const COMMANDS = {
    0x00: 'PLAY FOLDER',
    0x01: 'PLAYBACK',
    0x02: 'STANDBY/WAKEUP',
    0x03: 'HDMI-CEC',
    0x05: 'PJLINK'
  };

  function readStr(buf, off, len) {
    let s = '';
    for (let i = off; i < off + len; i++) {
      const c = buf[i];
      if (c === 0xff) break;
      s += String.fromCharCode(c);
    }
    return s;
  }

  function parse(buf) {
    const dv = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
    function u16(off) { return dv.getUint16(off, true); }

    const hdr = {
      ver: readStr(buf, 0x000, 8),
      device: readStr(buf, 0x008, 0x78),
      name: readStr(buf, 0x080, 128),
      author: readStr(buf, 0x100, 128),
      moddate: readStr(buf, 0x180, 0x20),
      client: readStr(buf, 0x1a0, 128),
      comments: readStr(buf, 0x220, 1024),
      softver: readStr(buf, 0x620, 0x20)
    };
    const ndays = u16(0x640);
    const nevents = u16(0x642);

    // calendar: date -> typical day index
    const dates = {};
    for (let y = 2000; y < 2099; y++) {
      for (let doy = 0; doy < 366; doy++) {
        const off = CAL_BASE + 2 * (doy + 366 * (y - 2000));
        if (off + 2 > buf.length) break;
        const v = u16(off);
        if (v !== 0xffff) {
          const d = new Date(Date.UTC(y, 0, 1 + doy));
          dates[d.toISOString().slice(0, 10)] = v;
        }
      }
    }

    // typical days (minute blocks + titles)
    const days = [];
    for (let k = 0; k < ndays; k++) {
      const base = BASE + k * MINUTE_BLOCK;
      const events = [];
      for (let min = 0; min < 1440; min++) {
        const v = u16(base + min * 2);
        if (v !== 0xffff) {
          events.push({ minute: min, code: v >> 12, value: v & 0xfff });
        }
      }
      const tbase = BASE + ndays * MINUTE_BLOCK + k * DAY_TITLE;
      days.push({
        name: readStr(buf, tbase, 128),
        color: [buf[tbase + 128], buf[tbase + 129], buf[tbase + 130]],
        events
      });
    }

    // sequential event list (with comments)
    const sevents = [];
    for (let k = 0; k < nevents; k++) {
      const base = BASE + ndays * 3072 + k * EVENT_SLOT;
      const v = u16(base);
      sevents.push({ code: v >> 12, value: v & 0xfff, comment: readStr(buf, base + 2, 128) });
    }

    return { hdr, ndays, nevents, dates, days, sevents };
  }

  function encode(model) {
    const ndays = model.days.length;
    const nevents = model.days.reduce((n, d) => n + d.events.length, 0);
    const total = BASE + ndays * 3072 + nevents * EVENT_SLOT;
    const buf = new Uint8Array(total).fill(0xff);

    function putStr(off, s, len) {
      if (!s) return;
      const b = s.slice(0, len);
      for (let i = 0; i < b.length; i++) buf[off + i] = b.charCodeAt(i) & 0xff;
    }
    function putU16(off, v) { buf[off] = v & 0xff; buf[off + 1] = (v >> 8) & 0xff; }

    const h = model.hdr;
    putStr(0x000, h.ver, 8);
    putStr(0x008, h.device, 0x78);
    putStr(0x080, h.name, 128);
    putStr(0x100, h.author, 128);
    putStr(0x180, h.moddate, 0x20);
    putStr(0x1a0, h.client, 128);
    putStr(0x220, h.comments, 1024);
    putStr(0x620, h.softver, 0x20);
    putU16(0x640, ndays);
    putU16(0x642, nevents);

    // calendar
    for (const iso in model.dates) {
      const [y, mo, d] = iso.split('-').map(Number);
      const doy = Math.round((Date.UTC(y, mo - 1, d) - Date.UTC(y, 0, 1)) / 86400000);
      const off = CAL_BASE + 2 * (doy + 366 * (y - 2000));
      putU16(off, model.dates[iso]);
    }

    // minute blocks + titles
    for (let k = 0; k < ndays; k++) {
      const day = model.days[k];
      const base = BASE + k * MINUTE_BLOCK;
      for (const e of day.events) putU16(base + e.minute * 2, (e.code << 12) | e.value);
      const tbase = BASE + ndays * MINUTE_BLOCK + k * DAY_TITLE;
      putStr(tbase, day.name, 128);
      if (day.color && day.color.length >= 3) {
        buf[tbase + 128] = day.color[0];
        buf[tbase + 129] = day.color[1];
        buf[tbase + 130] = day.color[2];
      }
    }

    // sequential event list
    let idx = 0;
    for (const day of model.days) {
      for (const e of day.events) {
        const base = BASE + ndays * 3072 + idx * EVENT_SLOT;
        putU16(base, (e.code << 12) | e.value);
        putStr(base + 2, e.comment, 128);
        idx++;
      }
    }

    return buf;
  }

  function fmtTime(minute) {
    return String(Math.floor(minute / 60)).padStart(2, '0') + ':' +
           String(minute % 60).padStart(2, '0');
  }

  function fmtEvent(e) {
    return (COMMANDS[e.code] || 'CMD ' + e.code) + ' ' + e.value;
  }

  return { parse, encode, COMMANDS, fmtTime, fmtEvent };
});
